  (* [comment removed for export] *)
  Lemma xpres_drop_stack : forall s LB m0 SP SP' X Y m m',
    as_RHEAP H s LB m0 ->
    xpres H LB SP' (X ++ Y) m m' -> SP' <= SP ->
    Forall (fun iv : Z * Z => aceil <= fst iv /\ snd iv <= SP) Y ->
    xpres H LB SP X m m'.
  Proof.
    intros s LB m0 SP SP' X Y m m' RH XP HS FY a Ha [Hc NX]. apply XP; [exact Ha|]. split.
    - eapply aclient_addr_weaken; [exact Hc| exact HS| intros b Hb; exact Hb].
    - intros K. apply rin_ivs_app in K. destruct K as [K|K]; [exact (NX K)|].
      assert (IN : exists l h, aceil <= l /\ h <= SP /\ l <= a < h).
      { clear - FY K. induction Y as [|[l h] Y IH]; [destruct K|]. cbn in K. pose proof (Forall_inv FY) as F1. cbn in F1.
        destruct K as [K|K]; [exists l, h; lia| exact (IH (Forall_inv_tail FY) K)]. }
      destruct IN as (l & h & I1 & I2 & I3).
      pose proof (aclient_below_sp s LB m0 SP a RH Hc ltac:(lia)). lia.
  Qed.

End HCW.
